// Change priority type based on the passed key.
const notificationBox = this.globalBox;
let priority = notificationBox.PRIORITY_WARNING_HIGH;
let dismissable = true;
switch (key) {
  case "otr:auth-error":
  case "otr:auth-fail":
    priority = notificationBox.PRIORITY_CRITICAL_HIGH;
    break;
  case "otr:auth-waiting":
    priority = notificationBox.PRIORITY_INFO_MEDIUM;
    dismissable = false;
    break;

  default:
    break;
}

OTRUI.closeUnverifiedWithUsername(cachedUsername);

const notification = await notificationBox.appendNotification(
  cachedUsername,
  {
    label: authLabelMap.get(key),
    priority,
  },
  buttons
);

// Set the user attribute so we can show and hide notifications based on the
// currently viewed conversation.
notification.setAttribute("user", cachedUsername);
// Set custom attributes for CSS styling.
notification.setAttribute("protocol", "otr");
notification.setAttribute("status", key);
